import { useState } from 'react';
import { Outlet, useNavigate, useLocation } from 'react-router-dom';
import { Layout as AntLayout, Menu, theme, Avatar, Dropdown, Space, Tag } from 'antd';
import type { MenuProps } from 'antd';
import {
  DashboardOutlined,
  BellOutlined,
  UserAddOutlined,
  FolderAddOutlined,
  CalendarOutlined,
  NotificationOutlined,
  CheckSquareOutlined,
  SolutionOutlined,
  BankOutlined,
  FileTextOutlined,
  DatabaseOutlined,
  DollarOutlined,
  ShoppingCartOutlined,
  SettingOutlined,
  MenuFoldOutlined,
  MenuUnfoldOutlined,
  TeamOutlined,
  LogoutOutlined,
  UserOutlined,
} from '@ant-design/icons';
import { useAuthStore } from '../store/auth';
import { ActivityBell } from './ActivityBell';
import { Chat } from './Chat';
import logoFull from '/logo.svg';
import logoIcon from '/logo-icon.svg';

const { Sider, Header, Content } = AntLayout;

const allMenuItems = [
  { key: '/', icon: <DashboardOutlined />, label: 'لوحة التحكم', module: 'dashboard' },
  { key: '/notifications', icon: <BellOutlined />, label: 'التنبيهات', module: 'notifications' },
  { key: '/customers', icon: <UserAddOutlined />, label: 'العملاء', module: 'customers' },
  { key: '/cases', icon: <FolderAddOutlined />, label: 'القضايا', module: 'cases' },
  { key: '/sessions', icon: <CalendarOutlined />, label: 'الجلسات', module: 'sessions' },
  { key: '/announcements', icon: <NotificationOutlined />, label: 'الإعلانات', module: 'announcements' },
  { key: '/tasks', icon: <CheckSquareOutlined />, label: 'المهام', module: 'tasks' },
  { key: '/customer-dossier', icon: <SolutionOutlined />, label: 'ملف الموكل الشامل', module: 'customers' },
  { key: '/court-dossier', icon: <BankOutlined />, label: 'ملف المحكمة', module: 'cases' },
  { key: '/templates', icon: <FileTextOutlined />, label: 'النماذج', module: 'templates' },
  { key: '/settings/backup', icon: <DatabaseOutlined />, label: 'النسخ الاحتياطي', module: 'backup' },
  {
    key: 'accounts',
    icon: <DollarOutlined />,
    label: 'الحسابات',
    children: [
      { key: '/fees', icon: <DollarOutlined />, label: 'الأتعاب', module: 'fees' },
      { key: '/expenses', icon: <ShoppingCartOutlined />, label: 'المصروفات', module: 'expenses' },
    ],
  },
  {
    key: 'elements',
    icon: <SettingOutlined />,
    label: 'الإعدادات',
    children: [
      { key: '/settings/case-types', icon: <FolderAddOutlined />, label: 'أنواع القضايا', module: 'settings' },
      { key: '/settings/announcement-types', icon: <NotificationOutlined />, label: 'أنواع الإعلانات', module: 'settings' },
      { key: '/settings/courts', icon: <BankOutlined />, label: 'المحاكم', module: 'settings' },
      { key: '/settings/lawyer-profile', icon: <SolutionOutlined />, label: 'بيانات المحامي', module: 'settings' },
    ],
  },
  { key: '/users', icon: <TeamOutlined />, label: 'إدارة المستخدمين', module: 'users' },
];

const roleLabels: Record<string, string> = {
  admin: 'مدير',
  lawyer: 'محامي',
  secretary: 'سكرتير',
};

const roleColors: Record<string, string> = {
  admin: '#C9A227',
  lawyer: '#2980b9',
  secretary: '#27ae60',
};

export function Layout() {
  const [collapsed, setCollapsed] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  const { token } = theme.useToken();
  const { user, logout, hasPermission, canAccess } = useAuthStore();

  const selectedKey = location.pathname;
  const openKeys: string[] = [];
  if (selectedKey.startsWith('/fees') || selectedKey.startsWith('/expenses')) openKeys.push('accounts');
  if (selectedKey.startsWith('/settings/')) openKeys.push('elements');

  // تصفية عناصر القائمة بناءً على الصلاحيات
  const filterMenuItems = (items: any[]): any[] => {
    return items
      .filter(item => {
        if (item.children) return true;
        return canAccess(item.key);
      })
      .map(item => {
        if (item.children) {
          const children = item.children.filter((c: any) => canAccess(c.key));
          if (children.length === 0) return null;
          return { ...item, children };
        }
        return item;
      })
      .filter(Boolean);
  };

  const visibleMenuItems = filterMenuItems(allMenuItems);

  // Find the current page label
  const findLabel = (key: string): string => {
    for (const item of allMenuItems) {
      if (item.key === key) return item.label as string;
      const children = (item as any).children;
      if (children) {
        for (const child of children) {
          if (child.key === key) return child.label as string;
        }
      }
    }
    return 'LEX PRO';
  };

  const dropdownItems: MenuProps['items'] = [
    {
      key: 'profile',
      icon: <UserOutlined />,
      label: 'الملف الشخصي',
      onClick: () => navigate('/profile'),
    },
    { type: 'divider' },
    {
      key: 'logout',
      icon: <LogoutOutlined />,
      label: 'تسجيل الخروج',
      onClick: () => {
        logout();
        navigate('/login');
      },
    },
  ];

  return (
    <AntLayout style={{ minHeight: '100vh' }}>
      <Sider
        trigger={null}
        collapsible
        collapsed={collapsed}
        theme="dark"
        width={220}
        collapsedWidth={60}
        style={{
          background: 'linear-gradient(180deg, #1a2332 0%, #1e2a3a 100%)',
          boxShadow: '2px 0 8px rgba(0,0,0,0.15)',
          position: 'sticky',
          top: 0,
          height: '100vh',
          overflow: 'auto',
        }}
      >
        <div style={{
          height: 54,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          borderBottom: '1px solid rgba(255,255,255,0.08)',
          padding: collapsed ? '4px' : '4px 14px',
          background: 'rgba(0,0,0,0.15)',
        }}>
          <img
            src={collapsed ? logoIcon : logoFull}
            alt="LEX PRO"
            style={{
              height: collapsed ? 30 : 34,
              objectFit: 'contain',
              transition: 'all 0.2s ease',
            }}
          />
        </div>

        <Menu
          mode="inline"
          selectedKeys={[selectedKey]}
          defaultOpenKeys={openKeys}
          items={visibleMenuItems}
          onClick={({ key }) => navigate(key)}
          theme="dark"
          style={{
            background: 'transparent',
            borderInlineEnd: 'none',
            padding: '6px 0',
            fontSize: 13,
          }}
        />
      </Sider>

      <AntLayout>
        <Header style={{
          background: token.colorBgContainer,
          padding: '0 16px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 12,
          borderBottom: `1px solid ${token.colorBorderSecondary}`,
          height: 52,
          position: 'sticky',
          top: 0,
          zIndex: 10,
          boxShadow: '0 2px 8px rgba(0,0,0,0.06)',
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
            <span
              onClick={() => setCollapsed(!collapsed)}
              style={{
                fontSize: 17,
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                padding: '4px',
                borderRadius: 6,
                transition: 'background 0.2s',
              }}
              onMouseEnter={(e) => e.currentTarget.style.background = token.colorFillSecondary}
              onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
            >
              {collapsed ? <MenuUnfoldOutlined /> : <MenuFoldOutlined />}
            </span>
            <span style={{
              fontSize: 15,
              fontWeight: 600,
              color: '#2c3e50',
            }}>
              {findLabel(selectedKey)}
            </span>
          </div>

          {/* الإشعارات + معلومات المستخدم */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <ActivityBell />
            <Chat />
            {user && (
            <Dropdown menu={{ items: dropdownItems }} placement="bottomLeft">
              <div style={{
                display: 'flex',
                alignItems: 'center',
                gap: 8,
                cursor: 'pointer',
                padding: '4px 8px',
                borderRadius: 8,
                transition: 'background 0.2s',
              }}
                onMouseEnter={(e) => e.currentTarget.style.background = token.colorFillSecondary}
                onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
              >
                <Avatar
                  src={user.avatar || undefined}
                  style={{
                    background: roleColors[user.role] || '#2c3e50',
                    fontSize: 14,
                    size: 32,
                  }}
                  icon={!user.avatar && <UserOutlined />}
                >
                  {!user.avatar && (user.name?.charAt(0) || '؟')}
                </Avatar>
                <div style={{ lineHeight: 1.2 }}>
                  <div style={{ fontSize: 13, fontWeight: 600, color: '#2c3e50' }}>{user.name}</div>
                  <Tag color={roleColors[user.role]} style={{ fontSize: 10, margin: 0, lineHeight: '16px', padding: '0 4px' }}>
                    {roleLabels[user.role] || user.role}
                  </Tag>
                </div>
              </div>
            </Dropdown>
          )}
          </div>
        </Header>
        <Content style={{
          margin: 0,
          padding: 14,
          overflow: 'auto',
          background: '#f0f2f5',
        }}>
          <Outlet />
        </Content>
      </AntLayout>
    </AntLayout>
  );
}

import { Button, Space, Input } from 'antd';
import { PlusOutlined, EditOutlined, DeleteOutlined, SearchOutlined } from '@ant-design/icons';
import { Typography } from 'antd';

const { Title, Text } = Typography;

interface PageHeaderProps {
  title: string;
  subtitle?: string;
  onAdd?: () => void;
  onEdit?: () => void;
  onDelete?: () => void;
  searchValue?: string;
  onSearch?: (value: string) => void;
  searchPlaceholder?: string;
  addLabel?: string;
  editLabel?: string;
  deleteLabel?: string;
}

export function PageHeader({
  title,
  subtitle,
  onAdd,
  onEdit,
  onDelete,
  searchValue,
  onSearch,
  searchPlaceholder = 'بحث...',
  addLabel = 'إضافة +',
  editLabel = 'تعديل',
  deleteLabel = 'حذف',
}: PageHeaderProps) {
  return (
    <div style={{ marginBottom: 12 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
        <div>
          <Title level={4} style={{ margin: 0, color: '#2c3e50' }}>{title}</Title>
          {subtitle && <Text type="secondary" style={{ fontSize: 13 }}>{subtitle}</Text>}
        </div>
        <Space size="middle">
          {onAdd && (
            <Button
              type="primary"
              icon={<PlusOutlined />}
              onClick={onAdd}
              style={{ background: '#27ae60', borderColor: '#27ae60', height: 38, paddingInline: 18, fontSize: 14 }}
            >
              {addLabel}
            </Button>
          )}
          {onEdit && (
            <Button
              icon={<EditOutlined />}
              onClick={onEdit}
              style={{ background: '#2980b9', borderColor: '#2980b9', color: '#fff', height: 38, paddingInline: 18, fontSize: 14 }}
            >
              {editLabel}
            </Button>
          )}
          {onDelete && (
            <Button
              danger
              icon={<DeleteOutlined />}
              onClick={onDelete}
              style={{ background: '#c0392b', borderColor: '#c0392b', height: 38, paddingInline: 18, fontSize: 14 }}
            >
              {deleteLabel}
            </Button>
          )}
        </Space>
      </div>
      {onSearch && (
        <Input
          placeholder={searchPlaceholder}
          value={searchValue}
          onChange={(e) => onSearch(e.target.value)}
          prefix={<SearchOutlined style={{ color: '#bfbfbf' }} />}
          style={{ maxWidth: 380 }}
        />
      )}
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { Table, Modal, Form, Input, Select, message, Row, Col, Upload, Button, Typography } from 'antd';
import type { UploadFile } from 'antd/es/upload/interface';
import {
  PlusOutlined, TeamOutlined, FileTextOutlined, SaveOutlined,
  UploadOutlined, PaperClipOutlined, FolderOpenOutlined,
  UserOutlined, SearchOutlined, BankOutlined, CalendarOutlined,
  NumberOutlined, FlagOutlined, EnvironmentOutlined, DeleteOutlined,
} from '@ant-design/icons';
import { createCrudApi, fileApi } from '../api/client';
import api from '../api/client';
import { PageHeader } from '../components/PageHeader';

const { Title, Text } = Typography;

const casesApi = createCrudApi('/cases');
const customersApi = createCrudApi('/customers');
const courtsApi = createCrudApi('/courts');
const caseTypesApi = createCrudApi('/case-types');
const caseDocsApi = createCrudApi('/case-documents');

export default function Cases() {
  const navigate = useNavigate();
  const [cases, setCases] = useState<any[]>([]);
  const [customers, setCustomers] = useState<any[]>([]);
  const [courts, setCourts] = useState<any[]>([]);
  const [caseTypes, setCaseTypes] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState('');
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [form] = Form.useForm();
  const [submitting, setSubmitting] = useState(false);
  const [selectedRowKeys, setSelectedRowKeys] = useState<any[]>([]);
  const [fileList, setFileList] = useState<UploadFile[]>([]);

  const fetchAll = useCallback(async () => {
    setLoading(true);
    try {
      const [casesRes, custRes, courtsRes, typesRes] = await Promise.all([
        casesApi.getAll(), customersApi.getAll(), courtsApi.getAll(), caseTypesApi.getAll(),
      ]);
      setCases(casesRes.data.data || casesRes.data || []);
      setCustomers(custRes.data.data || custRes.data || []);
      setCourts(courtsRes.data.data || courtsRes.data || []);
      setCaseTypes(typesRes.data.data || typesRes.data || []);
    } catch { message.error('حدث خطأ أثناء تحميل البيانات'); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { fetchAll(); }, [fetchAll]);

  const filtered = cases.filter((c: any) => {
    if (!search) return true;
    const q = search.toLowerCase();
    return (c.caseNumber || '').includes(q) || (c.customerName || '').toLowerCase().includes(q);
  });

  const openAdd = () => {
    setEditing(null);
    form.resetFields();
    setFileList([]);
    setModalOpen(true);
  };

  const openEdit = () => {
    if (selectedRowKeys.length === 0) {
      message.warning('يرجى اختيار قضية للتعديل');
      return;
    }
    const selected = cases.find((c) => c._id === selectedRowKeys[0]);
    if (!selected) return;
    setEditing(selected);
    form.setFieldsValue(selected);
    setFileList([]);
    setModalOpen(true);
  };

  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();
      setSubmitting(true);
      let caseId: string;

      if (editing?._id) {
        await casesApi.update(editing._id, values);
        caseId = editing._id;
        message.success('تم تحديث القضية');
      } else {
        const res = await casesApi.create(values);
        caseId = res.data.data?._id || res.data._id;
        message.success('تم إضافة القضية');
      }

      // رفع المرفقات
      if (fileList.length > 0 && caseId) {
        for (const file of fileList) {
          const rawFile = file.originFileObj;
          if (!rawFile) continue;
          const uploadRes = await fileApi.upload(rawFile);
          const fileId = uploadRes.data.data?.fileId || uploadRes.data.fileId;
          const fileName = uploadRes.data.data?.fileName || rawFile.name;
          await caseDocsApi.create({
            caseId,
            documentName: rawFile.name,
            documentType: 'مرفق',
            fileId,
            fileName,
            notes: '',
          });
        }
        message.success(`تم رفع ${fileList.length} مرفق`);
      }

      setModalOpen(false);
      fetchAll();
    } catch (e: any) { if (!e?.errorFields) message.error('حدث خطأ'); }
    finally { setSubmitting(false); }
  };

  const handleDelete = () => {
    if (selectedRowKeys.length === 0) {
      message.warning('يرجى اختيار قضية للحذف');
      return;
    }
    Modal.confirm({
      title: 'هل أنت متأكد من حذف هذه القضية؟',
      okText: 'نعم',
      cancelText: 'إلغاء',
      okButtonProps: { style: { background: '#c0392b', borderColor: '#c0392b' } },
      onOk: async () => {
        try {
          await Promise.all(selectedRowKeys.map((key) => casesApi.delete(key)));
          message.success('تم حذف القضية');
          setSelectedRowKeys([]);
          fetchAll();
        } catch { message.error('حدث خطأ أثناء الحذف'); }
      },
    });
  };

  const columns = [
    { title: 'رقم القضية', dataIndex: 'caseNumber', width: 80, render: (t: string, r: any) => <a onClick={() => navigate(`/cases/${r._id}`)}>{t}</a> },
    { title: 'السنة', dataIndex: 'caseYear', width: 60 },
    { title: 'الموكل', dataIndex: 'customerName', ellipsis: true },
    { title: 'صفة الموكل', dataIndex: 'clientCapacity', ellipsis: true },
    { title: 'الخصم', dataIndex: 'opponentName', ellipsis: true },
    { title: 'صفة الخصم', dataIndex: 'opponentCapacity', ellipsis: true },
    { title: 'المحكمة', dataIndex: 'courtName', ellipsis: true },
    { title: 'الدائرة', dataIndex: 'circuitNumber', width: 60 },
    { title: 'نوع القضية', dataIndex: 'caseTypeName', ellipsis: true },
    { title: 'الموضوع', dataIndex: 'caseSubject', ellipsis: true },
    { title: 'تاريخ الإضافة', dataIndex: 'createdDate', width: 100 },
  ];

  const currentYear = new Date().getFullYear();
  const yearOptions = Array.from({ length: 10 }, (_, i) => ({ value: currentYear - i, label: String(currentYear - i) }));

  return (
    <div>
      <PageHeader
        title="إدارة ملفات القضايا"
        subtitle="تسجيل قضايا الموكلين وربطها بالمحاكم والدوائر"
        onAdd={openAdd}
        onEdit={openEdit}
        onDelete={handleDelete}
        searchValue={search}
        onSearch={setSearch}
        addLabel="إضافة +"
      />
      <Table
        columns={columns}
        dataSource={filtered}
        rowKey="_id"
        loading={loading}
        size="small"
        rowSelection={{
          selectedRowKeys,
          onChange: (keys) => setSelectedRowKeys(keys),
        }}
        pagination={{ pageSize: 10 }}
      />

      <Modal
        open={modalOpen}
        onCancel={() => setModalOpen(false)}
        width={820}
        footer={null}
        destroyOnClose
        style={{ top: 20 }}
      >
        {/* Header */}
        <div style={{
          marginBottom: 20,
          display: 'flex',
          alignItems: 'center',
          gap: 10,
          paddingBottom: 12,
          borderBottom: '1px solid #f0f0f0',
        }}>
          <div style={{
            width: 40, height: 40, borderRadius: 8,
            background: 'linear-gradient(135deg, #27ae60, #2ecc71)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}>
            <FolderOpenOutlined style={{ color: '#fff', fontSize: 18 }} />
          </div>
          <div>
            <Title level={5} style={{ margin: 0 }}>
              {editing ? 'تعديل قضية' : 'إضافة قضية جديدة'}
            </Title>
            <Text type="secondary" style={{ fontSize: 12 }}>أدخل بيانات القضية وأطرافها</Text>
          </div>
        </div>

        <Form form={form} layout="vertical">
          {/* Section 1: Case Parties */}
          <div style={{
            background: '#fafbfc',
            borderRadius: 10,
            padding: '14px 16px 4px',
            marginBottom: 16,
            border: '1px solid #f0f0f0',
          }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 10 }}>
              <TeamOutlined style={{ color: '#C9A227' }} />
              <span style={{ fontWeight: 600, fontSize: 13, color: '#2c3e50' }}>أطراف القضية</span>
            </div>
            <Row gutter={16}>
              <Col span={8}>
                <Form.Item label="الموكل" name="customerId" rules={[{ required: true, message: 'يرجى اختيار الموكل' }]}>
                  <Select
                    showSearch
                    placeholder="اختر الموكل"
                    optionFilterProp="children"
                    options={customers.map((c: any) => ({ value: c._id, label: c.name }))}
                    suffixIcon={<UserOutlined />}
                    dropdownRender={(menu) => (
                      <>
                        {menu}
                        <div style={{ padding: 4, borderTop: '1px solid #e8e8e8', marginTop: 4 }}>
                          <Button type="text" icon={<PlusOutlined />} style={{ color: '#27ae60' }} onClick={() => navigate('/customers')} block>
                            إضافة موكل جديد
                          </Button>
                        </div>
                      </>
                    )}
                  />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item label="صفة الموكل" name="clientCapacity">
                  <Input placeholder="صفة الموكل" prefix={<FlagOutlined />} />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item label="نوع القضية" name="caseTypeId" rules={[{ required: true, message: 'يرجى اختيار نوع القضية' }]}>
                  <Select
                    showSearch
                    placeholder="اختر نوع القضية"
                    optionFilterProp="children"
                    options={caseTypes.map((c: any) => ({ value: c._id, label: c.name }))}
                    dropdownRender={(menu) => (
                      <>
                        {menu}
                        <div style={{ padding: 4, borderTop: '1px solid #e8e8e8', marginTop: 4 }}>
                          <Button type="text" icon={<PlusOutlined />} style={{ color: '#8e44ad' }} onClick={() => navigate('/settings/case-types')} block>
                            إضافة نوع قضية
                          </Button>
                        </div>
                      </>
                    )}
                  />
                </Form.Item>
              </Col>
            </Row>
            <Row gutter={16}>
              <Col span={8}>
                <Form.Item label="اسم الخصم" name="opponentName" rules={[{ required: true, message: 'يرجى إدخال اسم الخصم' }]}>
                  <Input placeholder="اسم الخصم" />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item label="صفة الخصم" name="opponentCapacity">
                  <Input placeholder="صفة الخصم" prefix={<FlagOutlined />} />
                </Form.Item>
              </Col>
              <Col span={8}>
